'use client';

import type { ReactNode } from 'react';
import './sliding-pagination.css';

export interface SlidingPaginationProps<T> {
  items: T[];
  pageSize: number;
  /** Current page, starting at 1. */
  page: number;
  onPageChange: (page: number) => void;
  renderItem: (item: T) => ReactNode;
  /** Accessible name, for example "Harbor results". */
  label: string;
  /** The page you came from, so the new page slides in from the right side. */
  previousPage?: number;
  className?: string;
}

/**
 * Each page slides in from the direction you are moving. The controls never
 * move, and the current page is announced in words.
 */
export function SlidingPagination<T>({
  items,
  pageSize,
  page,
  onPageChange,
  renderItem,
  label,
  previousPage,
  className = '',
}: SlidingPaginationProps<T>) {
  const pages = Math.max(1, Math.ceil(items.length / pageSize));
  const direction =
    previousPage === undefined || previousPage === page
      ? 'none'
      : page > previousPage
        ? 'forward'
        : 'back';
  const slice = items.slice((page - 1) * pageSize, page * pageSize);

  return (
    <nav className={`mg-pages ${className}`} aria-label={label}>
      <div className='mg-pages__window'>
        <ul key={page} className='mg-pages__list' data-direction={direction}>
          {slice.map((item, index) => (
            <li key={index}>{renderItem(item)}</li>
          ))}
        </ul>
      </div>
      <div className='mg-pages__controls'>
        <button
          type='button'
          disabled={page === 1}
          onClick={() => onPageChange(page - 1)}
          aria-label='Previous page'
        >
          ←
        </button>
        <ol>
          {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
            <li key={n}>
              <button
                type='button'
                aria-current={n === page ? 'page' : undefined}
                aria-label={`Page ${n}`}
                onClick={() => onPageChange(n)}
              >
                {n}
              </button>
            </li>
          ))}
        </ol>
        <button
          type='button'
          disabled={page === pages}
          onClick={() => onPageChange(page + 1)}
          aria-label='Next page'
        >
          →
        </button>
      </div>
      <p className='mg-pages__status' role='status'>
        Page {page} of {pages}
      </p>
    </nav>
  );
}

.mg-pages {
  display: grid;
  gap: 10px;
  color: var(--mg-text, #ffffff);
}

.mg-pages__window {
  overflow: hidden;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
}

.mg-pages__list {
  display: grid;
  min-height: 132px;
  margin: 0;
  padding: 6px;
  list-style: none;
}

.mg-pages__list li {
  padding: 8px 10px;
  border-radius: 6px;
}

.mg-pages__list li + li {
  border-top: 1px solid #262626;
}

.mg-pages__list[data-direction='forward'] {
  animation: mg-pages-from-right 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-pages__list[data-direction='back'] {
  animation: mg-pages-from-left 300ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-pages__controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.mg-pages__controls ol {
  display: flex;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mg-pages__controls button {
  min-width: 40px;
  min-height: 40px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 8px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-pages__controls button[aria-current='page'] {
  border-color: var(--mg-text, #ffffff);
  background: var(--mg-raised, #262626);
  color: #fff;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.mg-pages__controls button:disabled {
  opacity: 0.4;
  cursor: default;
}

.mg-pages__controls button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

.mg-pages__status {
  margin: 0;
  color: #b8b8b8;
  font-size: 13px;
  text-align: center;
}

@keyframes mg-pages-from-right {
  from {
    opacity: 0;
    transform: translateX(40px);
  }
}

@keyframes mg-pages-from-left {
  from {
    opacity: 0;
    transform: translateX(-40px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-pages__list[data-direction] {
    animation: none;
  }
}
